function first<T>(arr: T[]): T | undefined {
  return arr[0]
}

first([1, 2, 3])    // T = number, 戻り値: number | undefined
first(['a', 'b'])   // T = string

// 明示
first<number>([])   // T = number に固定

function byId<T extends { id: string }>(items: T[], id: string): T | undefined {
  return items.find((i) => i.id === id)
}

function prop<O, K extends keyof O>(o: O, k: K): O[K] {
  return o[k]
}

prop({ a: 1, b: 'x' }, 'a') // number
prop({ a: 1, b: 'x' }, 'b') // string
// prop({ a: 1 }, 'c')      // 型エラー

function create<T = string>(value?: T): T {
  return value as T
}

create()        // T = string（デフォルト）
create(10)      // T = number
create<boolean>() // T = boolean（明示）

// useState の型指定
const me = useState<{ id: string; name: string } | null>('me', () => null)

// 自前のコンポーザブル
function useToggle<T>(initial: T, alt: T) {
  const v = ref<T>(initial)
  function toggle() { v.value = v.value === initial ? alt : initial }
  return { v, toggle }
}

function pick<O, K extends keyof O>(o: O, k: K): O[K] {
  return o[k]
}

const r = pick({ a: 1, b: 'x' as const }, 'b')

